import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

const ACTION_FAILURE = "action_inspector_raise_failure";
const CUSTOM_TOOL_FAILURE = "Tool inspector_failure_marker used";

export const triggerActionFailureAndAssertError = async (page: Page) => {
  await test.step("Send inspector action failure trigger", async () => {
    await ui.inspectorShell.actions(page).sendMessage("inspector test action failure");
  });

  await test.step("Assert error dot and action event in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(ACTION_FAILURE);
    await ui.conversationLog.assertions(page).errorDotOnEventIsVisible(ACTION_FAILURE);
  });
};

export const openActionFailureDetailsAndAssertError = async (page: Page) => {
  await test.step("Click failed action event", async () => {
    await ui.conversationLog.actions(page).clickConversationEvent(ACTION_FAILURE);
  });

  await test.step("Assert error alert in action details", async () => {
    await ui.eventDetails.assertions(page).panelIsVisible("Action event details");
    await ui.eventDetails.assertions(page).errorAlertIsVisible();
    await ui.eventDetails.assertions(page).errorAlertContainsText("action_inspector_raise_failure");
  });
};

export const triggerCustomToolFailureAndAssertError = async (page: Page) => {
  await test.step("Send inspector custom tool failure trigger", async () => {
    const botCountBefore = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("inspector test custom tool failure");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(botCountBefore + 1);
  });

  await test.step("Assert error dot on tool event in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(CUSTOM_TOOL_FAILURE);
    await ui.conversationLog.assertions(page).errorDotOnEventIsVisible(CUSTOM_TOOL_FAILURE);
  });
};

export const openCustomToolFailureDetailsAndAssertError = async (page: Page) => {
  await test.step("Click failed MCP tool event", async () => {
    await ui.conversationLog.actions(page).clickConversationEvent(CUSTOM_TOOL_FAILURE);
  });

  await test.step("Assert error alert in MCP tool details", async () => {
    await ui.eventDetails.assertions(page).panelIsVisible("MCP tool executed");
    await ui.eventDetails.assertions(page).errorAlertIsVisible();
  });
};

export const triggerDirectMcpFailureAndAssertError = async (page: Page) => {
  await test.step("Send direct MCP failure trigger with collect follow-up", async () => {
    const botCountBefore = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("inspector test direct mcp failure");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(botCountBefore + 1);
    await ui.inspectorShell.actions(page).sendMessage("unreachable query");
  });

  await test.step("Assert MCP failure event in log", async () => {
    await ui.conversationLog
      .assertions(page)
      .conversationEventReached("Tool unavailable-tool used");
    await ui.conversationLog
      .assertions(page)
      .errorDotOnEventIsVisible("Tool unavailable-tool used");
  });
};

export const openDirectMcpFailureDetailsAndAssertError = async (page: Page) => {
  await test.step("Click failed direct MCP tool event", async () => {
    await ui.conversationLog.actions(page).clickConversationEvent("Tool unavailable-tool used");
  });

  await test.step("Assert MCP connection error in details", async () => {
    await ui.eventDetails.assertions(page).panelIsVisible("MCP tool executed");
    await ui.eventDetails.assertions(page).errorAlertIsVisible();
  });
};
